{
  "findings": [
    {
      "check_id": "CKV_AZURE_10",
      "title": "MSSQL Database should have Transparent Data Encryption (TDE) enabled",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "HIGH",
      "explanation": "The resource does not explicitly enable Transparent Data Encryption. While TDE is often enabled by default in Azure, explicit configuration ensures compliance and prevents accidental disabling or inheritance issues."
    },
    {
      "check_id": "CKV_AZURE_11",
      "title": "MSSQL Database should have a long-term retention policy for backups",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "The database lacks a `long_term_retention_policy` block. Without this, backups may only be retained for the short-term period (default 7 days), which is insufficient for disaster recovery and compliance requirements."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"trading_database\" {\n  name           = \"trading-database\"\n  server_id      = azurerm_mssql_server.trading_sql_server.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 100\n  sku_name       = \"S2\"\n  zone_redundant = false\n\n  transparent_data_encryption_enabled = true\n\n  long_term_retention_policy {\n    weekly_retention_in_weeks = 12\n    monthly_retention_in_weeks = 12\n    yearly_retention_in_weeks = 52\n    week_of_year              = 1\n  }\n}",
  "fix_summary": "Enabled Transparent Data Encryption (TDE) explicitly and added a long-term retention policy to ensure backups are kept for at least one year, improving security posture and disaster recovery capabilities."
}
